def _numeric_range(value):
    digits = str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789")
    value = str(value or "").translate(digits).strip()
    match = re.fullmatch(r"\s*(\d{1,6})\s*(?:[-–—]|تا|to)\s*(\d{1,6})(?:\s*[^\d]*)?", value, re.IGNORECASE)
    if match:
        low, high = int(match.group(1)), int(match.group(2))
        return (low, high) if high >= low else (None, None)
    match = re.fullmatch(r"\s*(\d{1,6})(?:\s*[^\d]*)?", value)
    if match:
        exact = int(match.group(1))
        return exact, exact
    return None, None


